export function runScriptcMain() {
  const key = "SCRIPTC_NPM_ASSIGN";
  process.title = "npm-assignment-shape";
  process.env[key] = "set";
  // OpenAI/Pi CLI startup shape: the no-op warning override is a temporary
  // fence outside this lane; the remaining direct product is measured here.
  // process.emitWarning = () => {};
  const url = new URL("https://example.com/old/path?q=1");
  const protocol = (url.protocol = "ftp");
  const pathname = (url.pathname = "/new path");
  const headers = { result: "old" };
  const result = (headers.result = protocol + ":" + pathname);
  return [process.title, process.env[key], url.href, headers.result, result].join("|");
}
